function handleUserSubmit(e) {
    e.preventDefault();
    const username = document.getElementById('userName').value.trim();
    const role = document.getElementById('userRole').value;
    const passwordField = document.getElementById('userPassword').value;
    const editUsername = document.getElementById('editUsername').value;

    if (editUsername) {
        const user = users.find(u => u.username === editUsername);
        if (user) {
            user.role = role;
            if (passwordField) user.password = passwordField;
        }
    } else {
        if (users.some(u => u.username === username)) {
            alert('Username already exists!');
            return;
        }
        
        const defaultPerms = role === 'Editor' 
            ? { placeOrder: true, editOrder: true, deleteOrder: true, addReceipt: true, addPayment: true }
            : { placeOrder: false, editOrder: false, deleteOrder: false, addReceipt: false, addPayment: false };
        users.push({ username, password: passwordField || '123456', role, permissions: defaultPerms });

    }
    saveState();
    closeModals();
}

function openUserModal() {
    if (!checkPermission('editOrder') && currentSession?.role !== 'Admin') {
        alert('You do not have permission to manage users.');
        return;
    }
    document.getElementById('userForm').reset();
    document.getElementById('editUsername').value = '';
    document.querySelector('#userModal h3').innerText = 'Add New User';
    document.getElementById('userName').disabled = false;
    document.getElementById('userModal').classList.add('active');
}

function editUser(username) {
    const user = users.find(u => u.username === username);
    if (!user) return;
    document.getElementById('userForm').reset();
    document.getElementById('editUsername').value = user.username;
    document.querySelector('#userModal h3').innerText = 'Edit User Permissions';
    document.getElementById('userName').value = user.username;
    document.getElementById('userName').disabled = true;
    document.getElementById('userRole').value = user.role;
    document.getElementById('userModal').classList.add('active');
}

function deleteUser(username) {
    if (username === 'admin') {
        alert('Cannot delete the main admin user.');
        return;
    }
    if (confirm('Are you sure you want to delete user "' + username + '"?')) {
        users = users.filter(u => u.username !== username);
        saveState();
    }
}

function saveRolePermissions(e) {
    if(e) e.preventDefault();
    const roles = ['Editor', 'Viewer'];
    const perms = ['placeOrder', 'editOrder', 'deleteOrder', 'addReceipt', 'addPayment', 'manageSuppliers', 'manageItems', 'manageBudget', 'accessSettings', 'manageUsers'];
    
    roles.forEach(role => {
        perms.forEach(perm => {
            const el = document.getElementById('perm-' + role + '-' + perm);
            if (el) {
                rolePermissions[role][perm] = el.checked;
            }
        });
    });
    localStorage.setItem('procurement_permissions', JSON.stringify(rolePermissions));
    alert('Role permissions saved successfully!');
}

function applyRolePermissions() {
    const roles = ['Editor', 'Viewer'];
    const perms = ['placeOrder', 'editOrder', 'deleteOrder', 'addReceipt', 'addPayment', 'manageSuppliers', 'manageItems', 'manageBudget', 'accessSettings', 'manageUsers'];
    
    roles.forEach(role => {
        perms.forEach(perm => {
            const el = document.getElementById('perm-' + role + '-' + perm);
            if (el && rolePermissions[role]) {
                el.checked = rolePermissions[role][perm] === true;
            }
        });
    });
}

function checkPermission(permName) {
    if (!currentSession) return false;
    if (currentSession.role === 'Admin') return true;
    if (currentSession.permissions) {
        return currentSession.permissions[permName] === true;
    }
    return false;
}



function editUserPermissions(username) {
    const user = users.find(u => u.username === username);
    if (!user) return;
    document.getElementById('permUsername').value = user.username;
    document.getElementById('permUsernameDisplay').innerText = user.username;
    
    const perms = ['placeOrder', 'editOrder', 'deleteOrder', 'addReceipt', 'addPayment', 'manageSuppliers', 'manageItems', 'manageBudget', 'accessSettings', 'manageUsers'];
    perms.forEach(perm => {
        const el = document.getElementById('userPerm-' + perm);
        if (el) {
            el.checked = user.permissions ? (user.permissions[perm] === true) : false;
        }
    });
    
    document.getElementById('userPermissionsModal').classList.add('active');
}

function saveUserPermissions(e) {
    e.preventDefault();
    const username = document.getElementById('permUsername').value;
    const user = users.find(u => u.username === username);
    if (!user) return;
    
    if (!user.permissions) {
        user.permissions = {};
    }
    
    const perms = ['placeOrder', 'editOrder', 'deleteOrder', 'addReceipt', 'addPayment', 'manageSuppliers', 'manageItems', 'manageBudget', 'accessSettings', 'manageUsers'];
    perms.forEach(perm => {
        const el = document.getElementById('userPerm-' + perm);
        if (el) {
            user.permissions[perm] = el.checked;
        }
    });
    
    saveState();
    closeModals();
    alert('Permissions for ' + username + ' saved successfully!');
}

// Override login to include permissions in session
const originalHandleLogin = handleLogin;
handleLogin = function(e) {
    e.preventDefault();
    const username = document.getElementById('loginUsername').value.trim();
    const passwordField = document.getElementById('loginPassword').value;
    const user = users.find(u => u.username === username && u.password === passwordField);
    
    if (user) {
        currentSession = { username: user.username, role: user.role, permissions: user.permissions || {} };
        localStorage.setItem('procurement_session', JSON.stringify(currentSession));
        
        document.getElementById('login-screen').style.display = 'none';
        document.getElementById('appContainer').style.display = 'flex';
        renderAll();
    } else {
        document.getElementById('loginError').style.display = 'block';
    }
}



const originalApplyRolePermissions2 = (typeof applyRolePermissions === 'function') ? applyRolePermissions : function(){};
applyRolePermissions = function() {
    originalApplyRolePermissions2();
    if (checkPermission('manageUsers')) {
        document.getElementById('nav-users').style.display = 'flex';
    } else {
        document.getElementById('nav-users').style.display = 'none';
        if (document.getElementById('nav-users').classList.contains('active')) {
            switchTab('orders'); // fallback
        }
    }
    
    if (checkPermission('accessSettings')) {
        document.getElementById('nav-settings').style.display = 'flex';
    } else {
        document.getElementById('nav-settings').style.display = 'none';
        if (document.getElementById('nav-settings').classList.contains('active')) {
            switchTab('orders'); // fallback
        }
    }
    
    // Manage Budget tab
    if (checkPermission('manageBudget')) {
        document.getElementById('nav-budget').style.display = 'flex';
    } else {
        document.getElementById('nav-budget').style.display = 'none';
    }
    
    // Manage Suppliers tab
    if (checkPermission('manageSuppliers')) {
        document.getElementById('nav-suppliers').style.display = 'flex';
    } else {
        document.getElementById('nav-suppliers').style.display = 'none';
    }
    
    // Manage Items tab
    if (checkPermission('manageItems')) {
        document.getElementById('nav-items').style.display = 'flex';
    } else {
        document.getElementById('nav-items').style.display = 'none';
    }
};


function syncItemVotes() {
    const mainVote = document.getElementById('orderVote').value;
    if (mainVote) {
        const itemVotes = document.querySelectorAll('.item-vote');
        itemVotes.forEach(select => {
            select.value = mainVote;
        });
    }
}
